css:
.greenedge-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #16241d;
    background: linear-gradient(165deg, #eef3ec 0%, #e6efe7 55%, #dde9e2 100%);
    border-radius: 18px;
}

.greenedge-container * {
    box-sizing: border-box;
}

.greenedge-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f2a22 0%, #1c5039 55%, #2f7d4f 100%);
    color: #f0faf2;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(15, 42, 34, 0.32);
    position: relative;
    overflow: hidden;
}

.greenedge-header::after {
    content: "";
    position: absolute;
    right: -40px;
    top: -40px;
    width: 180px;
    height: 180px;
    background: radial-gradient(circle, rgba(120, 220, 150, 0.22) 0%, rgba(120, 220, 150, 0) 70%);
}

.greenedge-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.greenedge-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #b6f0c2;
    background: rgba(120, 220, 150, 0.14);
    border: 1px solid rgba(120, 220, 150, 0.38);
    padding: 5px 14px;
    border-radius: 999px;
    position: relative;
    z-index: 1;
}

.greenedge-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdebd4;
    position: relative;
    z-index: 1;
}

.greenedge-rivals {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.greenedge-rival {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(22, 36, 29, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.greenedge-rival-us { border-left: 5px solid #2f7d4f; }
.greenedge-rival-leaders { border-left: 5px solid #b06d12; }

.greenedge-rival-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #1c5039;
}

.greenedge-rival-leaders .greenedge-rival-name { color: #b06d12; }

.greenedge-rival-meta {
    font-size: 0.82rem;
    color: #5a6b62;
    line-height: 1.4;
}

.greenedge-rival-vs {
    align-self: center;
    font-size: 1.2rem;
    font-weight: 800;
    color: #2f7d4f;
    text-transform: uppercase;
}

.greenedge-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #45564c;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.greenedge-period-counter #currentDay,
.greenedge-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f7d4f;
}

.greenedge-round-name {
    background: rgba(47, 125, 79, 0.14);
    color: #1c5039;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.greenedge-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06d12;
    background: rgba(176, 109, 18, 0.12);
    border: 1px solid rgba(176, 109, 18, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.greenedge-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.greenedge-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(22, 36, 29, 0.08);
    border-top: 4px solid #2f7d4f;
}

.greenedge-card-diff { border-top-color: #2f7d4f; }
.greenedge-card-cost { border-top-color: #2563a8; }
.greenedge-card-emis { border-top-color: #1f8a76; }
.greenedge-card-share { border-top-color: #b06d12; }

.greenedge-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7d72;
}

.greenedge-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16241d;
    font-variant-numeric: tabular-nums;
}

.greenedge-card-diff .greenedge-value { color: #2f7d4f; }
.greenedge-card-cost .greenedge-value { color: #2563a8; }
.greenedge-card-emis .greenedge-value { color: #1f8a76; }
.greenedge-card-share .greenedge-value { color: #b06d12; }

.greenedge-sublabel {
    font-size: 0.76rem;
    color: #76887d;
    line-height: 1.35;
}

.greenedge-card-share.greenedge-share-danger { border-top-color: #d64545; }
.greenedge-card-share.greenedge-share-danger .greenedge-value { color: #d64545; }
.greenedge-card-share.greenedge-share-good { border-top-color: #2f7d4f; }
.greenedge-card-share.greenedge-share-good .greenedge-value { color: #2f7d4f; }

.greenedge-card-cost.greenedge-cost-good .greenedge-value { color: #1f8a76; }
.greenedge-card-cost.greenedge-cost-bad .greenedge-value { color: #d64545; }

.greenedge-meters {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
    flex-wrap: wrap;
}

.greenedge-meter {
    flex: 1;
    min-width: 240px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d6e2da;
    color: #45564c;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.greenedge-meter #budgetDisplay {
    color: #2563a8;
    font-weight: 800;
    font-size: 1.02rem;
}

.greenedge-meter #moatDisplay {
    color: #b06d12;
    font-weight: 800;
    font-size: 1.02rem;
}

.greenedge-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f7d4f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(22, 36, 29, 0.07);
}

.greenedge-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.greenedge-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1c5039;
    margin-bottom: 6px;
}

.greenedge-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4b41;
}

.greenedge-briefing-text strong { color: #1c5039; }
.greenedge-briefing-text em { color: #b06d12; font-style: italic; }

.greenedge-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(22, 36, 29, 0.07);
}

.greenedge-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1c5039;
    border-bottom: 2px solid #e3ece6;
    padding-bottom: 8px;
}

.greenedge-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3c33;
    margin: 14px 0 6px;
}

.greenedge-container select,
.greenedge-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c4d4ca;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #16241d;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.greenedge-container select:focus,
.greenedge-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d4f;
    box-shadow: 0 0 0 3px rgba(47, 125, 79, 0.16);
}

.greenedge-container select option {
    background-color: #ffffff;
    color: #16241d;
}

.greenedge-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d4f;
}

.greenedge-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #45564c;
    margin-top: 4px;
}

.greenedge-range-readout span:nth-child(2),
.greenedge-range-readout span:nth-child(5) {
    color: #2f7d4f;
    font-weight: 800;
}

.greenedge-hint {
    font-size: 0.8rem;
    color: #76887d;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.greenedge-policy {
    background: linear-gradient(135deg, #fff7e8 0%, #fdeecf 100%);
    border: 1px solid #e7c889;
    border-left: 5px solid #b06d12;
    border-radius: 10px;
    padding: 12px 16px;
    margin-bottom: 8px;
}

.greenedge-policy-title {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 800;
    color: #b06d12;
    margin-bottom: 4px;
}

.greenedge-policy-text {
    font-size: 0.9rem;
    line-height: 1.5;
    color: #6d5212;
}

.greenedge-policy-text strong { color: #8a4f0d; }

.greenedge-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.greenedge-container .btn-primary {
    background: linear-gradient(135deg, #1c5039 0%, #2f7d4f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(28, 80, 57, 0.32);
}

.greenedge-container .btn-primary:hover {
    filter: brightness(1.08);
}

.greenedge-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c4d4ca;
    color: #5a6b62;
    background: transparent;
}

.greenedge-coach {
    background: linear-gradient(160deg, #0f2a22 0%, #163b2c 100%);
    color: #dff0e4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(15, 42, 34, 0.26);
}

.greenedge-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b6f0c2;
    margin-bottom: 8px;
}

.greenedge-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.greenedge-coach-body strong { color: #7fe0a0; }
.greenedge-coach-body em { color: #ffd79a; font-style: italic; }

.greenedge-history,
.greenedge-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(22, 36, 29, 0.07);
}

.greenedge-history h3,
.greenedge-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1c5039;
}

.greenedge-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4b41;
}

.greenedge-container table#usfHistoryTable th {
    background: #eaf3ed;
    color: #1c5039;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e3da;
}

.greenedge-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eaf1ec;
    color: #3a4b41;
}

.greenedge-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f5faf6;
}

.greenedge-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .greenedge-container {
        padding: 14px;
    }
    .greenedge-header h1 {
        font-size: 1.7rem;
    }
    .greenedge-rivals {
        flex-direction: column;
    }
    .greenedge-rival-vs {
        transform: rotate(90deg);
    }
    .greenedge-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .greenedge-value {
        font-size: 2rem;
    }
    .greenedge-clock {
        margin-left: 0;
    }
    .greenedge-period-counter {
        font-size: 0.88rem;
    }
    .greenedge-meters {
        flex-direction: column;
    }
    .greenedge-meter {
        min-width: 0;
    }
    .greenedge-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.ge-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.ge-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #6f8a72; margin-bottom: 6px; }
.ge-cm-verdict { font-size: 22px; font-weight: 700; color: #16311c; margin-bottom: 8px; }
.ge-cm-score { font-size: 16px; color: #16311c; margin-bottom: 16px; }
.ge-cm-score strong { color: #2f8f4e; }
.ge-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #6f8a72; margin-bottom: 8px; }
.ge-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.ge-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.ge-cm-target.ge-cm-met { background: #e6f4ea; color: #1c6b39; border-color: #b8e0c6; }
.ge-cm-target.ge-cm-missed { background: #fdeceb; color: #9a342c; border-color: #f2c9c4; }
.ge-cm-tick { font-weight: 700; }
.ge-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.ge-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: #eef4f0; border-radius: 8px; min-width: 92px; }
.ge-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #6f8a72; }
.ge-cm-metric strong { font-size: 16px; color: #16311c; }
.ge-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.ge-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: #eef6f0; border-left: 3px solid #2f8f4e; border-radius: 4px; color: #1f3a26; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .ge-cm-metric { min-width: 70px; } .ge-cm-verdict { font-size: 19px; } }

