(function() {
    'use strict';

    class GreenEdgeAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Green Edge`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Alpina Domus d.o.o.). ----
            this.BUDGET_CAP = 9.0;          // €9.0M fixed green-innovation budget
            this.START_DIFF = 40;           // differentiation index (0–100), 1 class behind leaders
            this.START_COST = 100;          // unit-cost index, 100 = today (lower better)
            this.START_EMIS = 0;            // Scope-2 reduction %, baseline
            this.START_SHARE = 12.0;        // EU appliance market share %
            this.AT_RISK_REVENUE = 83;      // €83M of revenue at the regulatory cliff (38% of SKUs)
            this.WHITE_LABEL_VOL = 46;      // % of volume from white-label
            this.DUAL_SOURCE_RISK = 41;     // €41M further volume at risk

            // ---- Concept truths (the modelled best answers). ----
            this.TRUE_BINDING = `product`;      // product performance AND emissions, together
            this.TRUE_STANCE = `selective`;     // selective proactivity beats both extremes under uncertainty
            this.TRUE_THESIS = `both`;          // product+process complementarity
            this.TRUE_MOAT = `capability`;      // valuable, rare, hard-to-imitate
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    diff: this.START_DIFF,           // differentiation index 0–100
                    cost: this.START_COST,           // unit-cost index (lower better)
                    emis: this.START_EMIS,           // Scope-2 reduction %
                    share: this.START_SHARE,         // market share %
                    budgetSpent: 0,                  // €M committed of the 9.0 cap
                    productSpend: 0,                  // €M into green product
                    processSpend: 0,                  // €M into green process
                    complianceOnly: false,            // ran the pure-compliance trap
                    productOnly: false,               // all-in product, brown factory
                    processOnly: false,               // all-in process, invisible to customer
                    subsidyBet: false,                // built the case on the un-enacted subsidy
                    channelBlindSpot: true,           // ignoring the 46% white-label
                    moat: `none`,                     // what protects the edge
                    policyState: ``,                  // revealed in round 3
                    subsidyEnacted: false,
                    carbonConfirmed: false,
                    diffHistory: [this.START_DIFF],
                    costHistory: [this.START_COST],
                    emisHistory: [this.START_EMIS],
                    shareHistory: [this.START_SHARE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors so a blind
                // click-through does NOT auto-win.
                state.decisions = {
                    binding: `brand`,
                    skus: `ignore`,
                    posture: `reactive`,
                    channel: 20,
                    alloc: 100,        // 100% product, 0% process — the imbalance trap
                    stance: `reactive`,
                    thesis: `none`,
                    process: `accelerate`,
                    subsidy: `allin`,
                    carbon: `ignore`,
                    pricing: `cut`,
                    moat: `nothing`,
                    channelMove: `ignore`,
                    pitch: `compliance`,
                    conviction: 50
                };
            }
            this._rollPolicy(state);
            this._updateBriefing(state);
        }

        // Deterministically derive the Round-3 policy shocks from a stable seed
        // so the revealed state is consistent across re-renders within a session.
        _rollPolicy(state) {
            const ds = state.domainState;
            if (ds.policyState) return;
            // Two of three shocks drawn "live": subsidy state + carbon-border state.
            // Use a light seed so a session is stable but not always identical.
            const seed = (Date.now() % 3);
            if (seed === 0) { ds.policyState = `delayed`; ds.subsidyEnacted = false; ds.carbonConfirmed = true; }
            else if (seed === 1) { ds.policyState = `enacted`; ds.subsidyEnacted = true; ds.carbonConfirmed = false; }
            else { ds.policyState = `cancelled`; ds.subsidyEnacted = false; ds.carbonConfirmed = true; }
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const bi = document.getElementById(`bindingInput`);
                const sk = document.getElementById(`skusInput`);
                const po = document.getElementById(`postureInput`);
                const ch = document.getElementById(`channelInput`);
                if (bi) decisions.binding = bi.value;
                if (sk) decisions.skus = sk.value;
                if (po) decisions.posture = po.value;
                if (ch) decisions.channel = parseInt(ch.value, 10);
                if (!Number.isFinite(decisions.channel) || decisions.channel < 0 || decisions.channel > 100) {
                    warn(`warn_channel_range`); return false;
                }
            } else if (round === 2) {
                const al = document.getElementById(`allocInput`);
                const st = document.getElementById(`stanceInput`);
                const th = document.getElementById(`thesisInput`);
                if (al) decisions.alloc = parseInt(al.value, 10);
                if (st) decisions.stance = st.value;
                if (th) decisions.thesis = th.value;
                if (!Number.isFinite(decisions.alloc) || decisions.alloc < 0 || decisions.alloc > 100) {
                    warn(`warn_alloc_range`); return false;
                }
            } else if (round === 3) {
                const pr = document.getElementById(`processInput`);
                const su = document.getElementById(`subsidyInput`);
                const ca = document.getElementById(`carbonInput`);
                const pc = document.getElementById(`pricingInput`);
                if (pr) decisions.process = pr.value;
                if (su) decisions.subsidy = su.value;
                if (ca) decisions.carbon = ca.value;
                if (pc) decisions.pricing = pc.value;
                if (!decisions.process) { warn(`warn_process_required`); return false; }
            } else if (round === 4) {
                const mo = document.getElementById(`moatInput`);
                const cm = document.getElementById(`channelMoveInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (mo) decisions.moat = mo.value;
                if (cm) decisions.channelMove = cm.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let diffDelta = 0, costDelta = 0, emisDelta = 0, shareDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the position (Common Error: compliance / brand-only / channel blind spot).
                switch (d.binding) {
                    case `product`: diffDelta += 3; coachKey = `coach_r1_product`; break;
                    case `brand`: diffDelta -= 2; coachKey = `coach_r1_brand`; break;
                    case `emissions`: emisDelta += 1; diffDelta -= 1; coachKey = `coach_r1_emissions`; break;
                    case `none`: diffDelta -= 4; shareDelta -= 0.3; coachKey = `coach_r1_none`; break;
                }

                switch (d.skus) {
                    case `audit`: diffDelta += 3; break;
                    case `topline`: diffDelta += 1; break;
                    case `ignore`: shareDelta -= 0.4; coachKey = `coach_r1_skuignore`; break;
                }

                switch (d.posture) {
                    case `proactive`: diffDelta += 2; break;
                    case `default`: break;
                    case `reactive`: diffDelta -= 2; ds.complianceOnly = true; break;
                }

                // Weighting the white-label channel correctly closes the blind spot.
                if (d.channel >= 50) { ds.channelBlindSpot = false; shareDelta += 0.3; }
                else if (d.channel <= 15) { shareDelta -= 0.4; if (coachKey === `coach_default`) coachKey = `coach_r1_channel`; }

                summaryKey = (d.binding === `product` && d.skus === `audit` && d.channel >= 50) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // The core bet: allocate €9.0M across product / process + stance (Common Errors 1, 2).
                const product = d.alloc / 100;          // share to product
                const process = 1 - product;             // share to process
                ds.productSpend = Math.round(this.BUDGET_CAP * product * 10) / 10;
                ds.processSpend = Math.round(this.BUDGET_CAP * process * 10) / 10;
                ds.budgetSpent = this.BUDGET_CAP;        // the full board-authorised cycle bet

                // Product innovation → differentiation (energy class, recycled content).
                diffDelta += 26 * product;
                // But product made in a brown plant raises unit cost.
                costDelta += 4 * product;

                // Process innovation → cost down + emissions down (Scope-2).
                costDelta -= 11 * process;
                emisDelta += 40 * process;
                // Process is weakly visible to the customer.
                diffDelta += 3 * process;

                // Complementarity: a balanced split earns a synergy bonus (Čater's nexus).
                const balance = 1 - Math.abs(product - 0.5) * 2;   // 1 at 50/50, 0 at extremes
                diffDelta += 6 * balance;
                costDelta -= 3 * balance;
                emisDelta += 6 * balance;

                // The two imbalance traps (decision tree #2 and #3).
                if (product >= 0.9) {
                    ds.productOnly = true; costDelta += 3; coachKey = `coach_r2_productonly`;
                } else if (process >= 0.9) {
                    ds.processOnly = true; diffDelta -= 6; coachKey = `coach_r2_processonly`;
                }

                // Stance.
                switch (d.stance) {
                    case `selective`: diffDelta += 6; shareDelta += 0.4; if (coachKey === `coach_default`) coachKey = `coach_r2_selective`; break;
                    case `leadership`: diffDelta += 9; costDelta += 5; shareDelta += 0.2; if (coachKey === `coach_default`) coachKey = `coach_r2_leadership`; break;
                    case `reactive`: diffDelta -= 6; ds.complianceOnly = true; coachKey = `coach_r2_reactive`; break;
                }

                // Advantage thesis.
                switch (d.thesis) {
                    case `both`: diffDelta += 4; shareDelta += 0.3; break;
                    case `premium`: diffDelta += 2; break;
                    case `cost`: costDelta -= 2; break;
                    case `none`: diffDelta -= 5; ds.complianceOnly = true; coachKey = `coach_r2_thesisnone`; break;
                }

                summaryKey = (d.alloc >= 40 && d.alloc <= 70 && d.stance === `selective` && d.thesis === `both`) ? `sum_r2_good` :
                             (ds.productOnly ? `sum_r2_productonly` :
                             (ds.processOnly ? `sum_r2_processonly` :
                             (d.stance === `reactive` || d.thesis === `none` ? `sum_r2_compliance` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Commit under policy uncertainty — real-options discipline (Common Error #3).
                const ps = ds.policyState;

                // Process tranche decision interacts with the revealed subsidy state.
                if (d.process === `phase`) {
                    // Real option: capture upside if enacted, limit downside if not.
                    emisDelta += 8; costDelta -= 2;
                    if (ds.subsidyEnacted) { costDelta -= 3; emisDelta += 6; coachKey = `coach_r3_phase_enacted`; }
                    else { coachKey = `coach_r3_phase_noenact`; }
                } else if (d.process === `accelerate`) {
                    emisDelta += 12; costDelta -= 4;
                    if (ds.subsidyEnacted) { costDelta -= 4; coachKey = `coach_r3_accel_enacted`; }
                    else {
                        // Committed the full tranche without the subsidy — underwater.
                        costDelta += 6; shareDelta -= 0.4; coachKey = `coach_r3_accel_noenact`;
                        if (d.subsidy === `allin`) { ds.subsidyBet = true; costDelta += 4; }
                    }
                } else { // hold
                    emisDelta -= 4; costDelta += 3; coachKey = `coach_r3_hold`;
                    if (ds.subsidyEnacted) shareDelta -= 0.3;   // froze through an enacted subsidy
                }

                // How much of the case rode on the subsidy.
                switch (d.subsidy) {
                    case `hedged`: costDelta -= 2; shareDelta += 0.2; if (coachKey === `coach_default`) coachKey = `coach_r3_hedged`; break;
                    case `some`: break;
                    case `allin`:
                        ds.subsidyBet = true;
                        if (!ds.subsidyEnacted) { costDelta += 5; shareDelta -= 0.5; coachKey = `coach_r3_subsidybet`; }
                        break;
                }

                // Carbon-border hedge on imported components.
                if (ds.carbonConfirmed) {
                    switch (d.carbon) {
                        case `localise`: costDelta -= 2; emisDelta += 4; break;       // cleaner process + local sourcing blunts the levy
                        case `absorb`: costDelta += 5; shareDelta -= 0.2; coachKey = (coachKey === `coach_default`) ? `coach_r3_carbonabsorb` : coachKey; break;
                        case `ignore`: costDelta += 6; shareDelta -= 0.3; coachKey = (coachKey === `coach_default`) ? `coach_r3_carbonignore` : coachKey; break;
                    }
                } else {
                    // Carbon-border shelved this draw — over-hedging it wastes a little.
                    if (d.carbon === `localise`) costDelta += 1;
                }

                // Pricing move on the redesigned own-brand line.
                switch (d.pricing) {
                    case `premium`:
                        // A premium only sticks if differentiation is real.
                        if (ds.diff >= 60) { shareDelta += 0.6; diffDelta += 2; }
                        else { shareDelta -= 0.6; coachKey = (coachKey === `coach_default`) ? `coach_r3_premium_thin` : coachKey; }
                        break;
                    case `cut`: shareDelta += 0.5; costDelta += 2; break;     // wins volume, squeezes margin
                    case `hold`: break;
                }

                summaryKey = (d.process === `phase` && d.subsidy !== `allin` && d.pricing !== `premium` || ds.diff >= 60) ? `sum_r3_good` : `sum_r3_weak`;
                if (ds.subsidyBet && !ds.subsidyEnacted) summaryKey = `sum_r3_subsidybet`;
            } else if (round === 4) {
                // Defend the advantage — the imitability test (Common Errors #4, #5).
                ds.moat = d.moat;
                switch (d.moat) {
                    case `capability`: diffDelta += 6; shareDelta += 0.6; coachKey = `coach_r4_capability`; break;
                    case `speed`: diffDelta += 1; shareDelta -= 0.2; coachKey = `coach_r4_speed`; break;
                    case `nothing`: diffDelta -= 4; shareDelta -= 0.5; coachKey = `coach_r4_nothing`; break;
                }

                // White-label channel move (decision tree #6).
                switch (d.channelMove) {
                    case `defend`: shareDelta += 0.8; ds.channelBlindSpot = false; if (coachKey === `coach_default`) coachKey = `coach_r4_channeldefend`; break;
                    case `ignore`: shareDelta -= 0.8; coachKey = `coach_r4_channelignore`; break;
                    case `exit`: shareDelta -= 1.4; coachKey = `coach_r4_channelexit`; break;
                }

                // The board pitch.
                switch (d.pitch) {
                    case `scorecard`: diffDelta += 3; shareDelta += 0.2; if (coachKey === `coach_default`) coachKey = `coach_r4_scorecard`; break;
                    case `onekpi`: diffDelta -= 1; coachKey = `coach_r4_onekpi`; break;
                    case `compliance`: diffDelta -= 4; ds.complianceOnly = true; coachKey = `coach_r4_compliance`; break;
                }

                // Conviction in the valuable-rare-inimitable standard.
                if (d.conviction >= 60) { diffDelta += 2; }
                else if (d.conviction <= 25) { diffDelta -= 2; }

                summaryKey = (d.moat === `capability` && d.channelMove === `defend` && d.pitch === `scorecard`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.diff = Math.max(0, Math.min(100, Math.round((ds.diff + diffDelta) * 10) / 10));
            ds.cost = Math.max(70, Math.min(120, Math.round((ds.cost + costDelta) * 10) / 10));
            ds.emis = Math.max(0, Math.min(100, Math.round((ds.emis + emisDelta) * 10) / 10));

            // ---- Market share is DERIVED from the four-KPI chain plus channel + cliff.
            // A visible differentiation edge wins share; a brown/expensive factory loses it;
            // failing the regulatory cliff loses the €83M at-risk revenue; the white-label
            // blind spot puts a further €41M at risk. ----
            const diffPull = (ds.diff - this.START_DIFF) / 100 * 1.6;        // differentiation wins customers
            const costPull = (this.START_COST - ds.cost) / 100 * 1.2;        // lower cost defends price
            const cliffPenalty = (ds.diff < 55 && state.currentPeriod >= 2) ? -0.5 : 0;  // still failing thresholds
            const channelPenalty = (ds.channelBlindSpot && state.currentPeriod >= 3) ? -0.6 : 0;
            shareDelta += diffPull + costPull + cliffPenalty + channelPenalty;
            ds.share = Math.max(6, Math.min(22, Math.round((ds.share + shareDelta) * 10) / 10));

            ds.diffHistory.push(ds.diff);
            ds.costHistory.push(ds.cost);
            ds.emisHistory.push(ds.emis);
            ds.shareHistory.push(ds.share);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                diff: ds.diff,
                diffDelta: Math.round(diffDelta * 10) / 10,
                cost: ds.cost,
                costDelta: Math.round(costDelta * 10) / 10,
                emis: ds.emis,
                emisDelta: Math.round(emisDelta * 10) / 10,
                share: ds.share,
                shareDelta: Math.round(shareDelta * 10) / 10,
                budgetSpent: ds.budgetSpent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`diffDisplay`, `domainState.diff`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`costDisplay`, `domainState.cost`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.greenedge-card-cost`);
                if (card) {
                    card.classList.toggle(`greenedge-cost-good`, n <= 96);
                    card.classList.toggle(`greenedge-cost-bad`, n >= 104);
                }
                return `${self._fmtNum(n)}`;
            });

            uiManager.bind(`emisDisplay`, `domainState.emis`, (v) => `${Math.round(Number(v))}%`);

            uiManager.bind(`shareDisplay`, `domainState.share`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.greenedge-card-share`);
                if (card) {
                    card.classList.toggle(`greenedge-share-danger`, n < self.START_SHARE - 0.5);
                    card.classList.toggle(`greenedge-share-good`, n >= self.START_SHARE + 1.5);
                }
                return `${self._fmtNum(n)}%`;
            });

            uiManager.bind(`budgetDisplay`, `domainState.budgetSpent`, (v) => `€${self._fmtNum(Number(v))}M / €${self._fmtNum(self.BUDGET_CAP)}M`);

            uiManager.bind(`moatDisplay`, `domainState.moat`, (v) => self._moatLabel(String(v)));

            // Channel slider readout (Round 1).
            const ch = document.getElementById(`channelInput`);
            const chReadout = document.getElementById(`channelReadout`);
            if (ch && chReadout) {
                chReadout.textContent = ch.value;
                ch.addEventListener(`input`, function() { chReadout.textContent = ch.value; });
            }

            // Allocation slider readout (Round 2) — product / process split.
            const al = document.getElementById(`allocInput`);
            const alProduct = document.getElementById(`allocProductReadout`);
            const alProcess = document.getElementById(`allocProcessReadout`);
            if (al && alProduct && alProcess) {
                const sync = function() {
                    alProduct.textContent = al.value;
                    alProcess.textContent = String(100 - parseInt(al.value, 10));
                };
                sync();
                al.addEventListener(`input`, sync);
            }
        }

        _fmtNum(v) {
            // Locale-aware one-decimal: en "12.0", es "12,0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        _moatLabel(code) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (code === `capability`) return t(`moat_val_capability`);
            if (code === `speed`) return t(`moat_val_speed`);
            if (code === `nothing`) return t(`moat_val_nothing`);
            return t(`moat_val_none`);
        }

        getChartConfig() {
            return {
                edgeChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Differentiation index (0–100)`,
                                data: [],
                                borderColor: `#2f7d4f`,
                                backgroundColor: `rgba(47,125,79,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f7d4f`,
                                yAxisID: `y`
                            },
                            {
                                label: `Emissions cut (%)`,
                                data: [],
                                borderColor: `#1f8a76`,
                                backgroundColor: `rgba(31,138,118,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#1f8a76`,
                                yAxisID: `y`
                            },
                            {
                                label: `Unit-cost index (100 = today)`,
                                data: [],
                                borderColor: `#2563a8`,
                                backgroundColor: `rgba(37,99,168,0.06)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
