        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.diffHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Share is ~6–22 — scale ×5 to share the 0–120 axis with index/percent series.
            const shareScaled = ds.shareHistory.map((v) => Math.round(v * 5));
            return {
                edgeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.diffHistory.map((v) => Math.round(v)) },
                        { data: ds.emisHistory.map((v) => Math.round(v)) },
                        { data: ds.costHistory.map((v) => Math.round(v)) },
                        { data: shareScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.34/0.22/0.20/0.24 sum to 1).
            const diff = Math.round(ds.diff);
            const cost = Math.round(ds.cost * 10) / 10;
            const emis = Math.round(ds.emis);
            const share = Math.round(ds.share * 10) / 10;
            const costScore = Math.max(0, Math.min(100, (this.START_COST - cost) / 15 * 100 + 50));
            const shareScore = Math.max(0, Math.min(100, (share - 6) / (22 - 6) * 100));
            return Math.round(diff * 0.34 + costScore * 0.22 + emis * 0.20 + shareScore * 0.24);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="ge-cm-target ' + (ok ? 'ge-cm-met' : 'ge-cm-missed') + '">'
                    + '<span class="ge-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.differentiated, t('tgt_diff'))
                + chip(!!summary.costAdvantaged, t('tgt_cost'))
                + chip(!!summary.cleaned, t('tgt_emis'))
                + chip(!!summary.grewShare, t('tgt_share'))
                + chip(!!summary.defensible, t('tgt_moat'));
            const metric = function (label, val) {
                return '<div class="ge-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const num = (typeof this._fmtNum === 'function') ? this._fmtNum.bind(this) : function (v) { return v; };
            const metrics = ''
                + metric(t('kpi_diff'), (summary.diff != null ? summary.diff : '-') + '/100')
                + metric(t('kpi_cost'), (summary.cost != null ? num(summary.cost) : '-'))
                + metric(t('kpi_emis'), (summary.emis != null ? summary.emis : '-') + '%')
                + metric(t('kpi_share'), (summary.share != null ? num(summary.share) : '-') + '%');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="ge-cm">'
                +   '<div class="ge-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="ge-cm-verdict">' + verdict + '</div>'
                +   '<div class="ge-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="ge-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="ge-cm-targets">' + targets + '</div>'
                +   '<div class="ge-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="ge-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const diff = Math.round(ds.diff);
            const cost = Math.round(ds.cost * 10) / 10;
            const emis = Math.round(ds.emis);
            const share = Math.round(ds.share * 10) / 10;

            // Composite advantage score (balanced across the four KPIs).
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula).
            const composite = this._composite(ds);

            const differentiated = diff >= 60;
            const costAdvantaged = cost <= 95;
            const cleaned = emis >= 30;
            const grewShare = share >= this.START_SHARE + 1.0;
            const defensible = ds.moat === `capability`;

            let pattern = `mixed`;
            if (ds.complianceOnly && diff < 55) pattern = `compliance`;
            else if (ds.productOnly && !costAdvantaged) pattern = `product_only`;
            else if (ds.processOnly && !differentiated) pattern = `process_only`;
            else if (ds.subsidyBet && !ds.subsidyEnacted) pattern = `subsidy`;
            else if (differentiated && costAdvantaged && cleaned && grewShare && defensible) pattern = `advantage`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (differentiated && costAdvantaged && cleaned && grewShare && defensible && composite >= 72) perfKey = `grade_advantage`;
            else if (differentiated && cleaned && grewShare && pattern !== `compliance`) perfKey = `grade_greenedge`;
            else if (pattern === `product_only`) perfKey = `grade_brownfactory`;
            else if (pattern === `process_only`) perfKey = `grade_invisible`;
            else if (pattern === `subsidy`) perfKey = `grade_subsidy`;
            else if (composite >= 52) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `advantage`) insights.push(window.mySimulation.t(`insight_advantage`));
            else if (pattern === `compliance`) insights.push(window.mySimulation.t(`insight_compliance`));
            else if (pattern === `product_only`) insights.push(window.mySimulation.t(`insight_product_only`));
            else if (pattern === `process_only`) insights.push(window.mySimulation.t(`insight_process_only`));
            else if (pattern === `subsidy`) insights.push(window.mySimulation.t(`insight_subsidy`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!defensible) insights.push(window.mySimulation.t(`insight_imitable`));
            if (ds.channelBlindSpot) insights.push(window.mySimulation.t(`insight_channel`));
            if (diff < 55) insights.push(window.mySimulation.t(`insight_cliff`));
            if (differentiated && !costAdvantaged) insights.push(window.mySimulation.t(`insight_costly_green`));
            if (cleaned && !differentiated) insights.push(window.mySimulation.t(`insight_invisible`));

            return {
                gradeKey: perfKey,
                score: composite,
                diff: diff,
                cost: cost,
                emis: emis,
                share: share,
                differentiated: differentiated,
                costAdvantaged: costAdvantaged,
                cleaned: cleaned,
                grewShare: grewShare,
                defensible: defensible,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.complianceOnly && ds.diff < 55) return window.mySimulation.t(`hint_compliance`);
            if (ds.productOnly && ds.cost > 100) return window.mySimulation.t(`hint_product_only`);
            if (ds.processOnly && ds.diff < 55) return window.mySimulation.t(`hint_process_only`);
            if (ds.subsidyBet && !ds.subsidyEnacted) return window.mySimulation.t(`hint_subsidy`);
            if (ds.channelBlindSpot && state.currentPeriod >= 3) return window.mySimulation.t(`hint_channel`);
            if (ds.moat !== `capability` && state.currentPeriod >= 4) return window.mySimulation.t(`hint_moat`);
            if (ds.diff >= 60 && ds.cost <= 95 && ds.emis >= 30 && ds.share >= this.START_SHARE + 1) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.diff`, label: `Diff`, i18nKey: `col_diff`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.cost`, label: `Cost`, i18nKey: `col_cost`, formatter: (v) => self._fmtNum(Number(v)) },
                { key: `results.emis`, label: `Emissions`, i18nKey: `col_emis`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.share`, label: `Share`, i18nKey: `col_share`, formatter: (v) => `${self._fmtNum(Number(v))}%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            // Round 3: reveal the live policy state in its box.
            const ds = (state.domainState) || (window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null);
            const policyEl = document.getElementById(`policyText`);
            if (policyEl && ds && ds.policyState) {
                policyEl.innerHTML = t(`policy_${ds.policyState}`);
            }

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

